  </div>

  <style>
    #chromosome-app .stage-btn[data-active="true"] {
      border-color: var(--viz-accent);
      background: var(--viz-accent-bg-subtle);
    }
  </style>

  <script>
    (() => {
      if (window.__chromosomeVizInit) return;
      window.__chromosomeVizInit = true;

      const stages = {
        '甲': {
          count: 8, ploidy: '2n', possible: '會出現', appear: '有絲分裂可出現',
          note: '甲的染色體雖呈 X 狀，但每個 X 仍算 1 條染色體；總數仍是 8 條。',
          explain: '<p><strong>甲：</strong>DNA 已經複製，所以染色體呈 X 狀，但仍是 8 條、2n。</p><p>有絲分裂前 DNA 會複製，因此受精卵發育過程中可以看到這種階段。</p>',
          type: 'x', n: 8
        },
        '乙': {
          count: 4, ploidy: 'n', possible: '不會出現', appear: '單套 n',
          note: '乙只有 4 條染色體。果蠅 2n = 8，因此 4 條代表單套 n。',
          explain: '<p><strong>乙：</strong>只有 4 條染色體，因此是 n。</p><p>受精卵發育成體時進行有絲分裂，正常體細胞維持 2n，所以這種單套階段不會出現。</p>',
          type: 'rod', n: 4
        },
        '丙': {
          count: 8, ploidy: '2n', possible: '會出現', appear: '有絲分裂可出現',
          note: '丙雖然看起來是單棒狀，但共有 8 條，因此仍是 2n，不是 n。',
          explain: '<p><strong>丙：</strong>染色體已分開呈棒狀，但總數是 8 條，所以仍屬 2n。</p><p>判斷 n / 2n 不能只看 X 或棒狀，要看整套同源染色體是否存在。</p>',
          type: 'rod', n: 8
        },
        '丁': {
          count: 4, ploidy: 'n', possible: '不會出現', appear: '單套 n',
          note: '丁只有 4 條染色體，也是單套 n；不是受精卵有絲分裂形成體細胞的正常階段。',
          explain: '<p><strong>丁：</strong>只有 4 條染色體，因此屬 n。</p><p>另外，DNA 複製發生在分裂前的間期，不是到了丁這個階段才開始複製。</p>',
          type: 'mixed', n: 4
        }
      };

      const svgGroup = document.getElementById('chromosomes');
      const centromeres = document.getElementById('centromeres');
      const buttons = [...document.querySelectorAll('.stage-btn')];

      function draw(stage) {
        const s = stages[stage];
        svgGroup.innerHTML = '';
        centromeres.innerHTML = '';
        const cx = 260, cy = 150;
        const positions = [
          [-62,-58],[-15,-70],[40,-57],[74,-18],
          [-70,28],[-25,55],[28,48],[70,35]
        ];
        for (let i = 0; i < s.n; i++) {
          const [dx,dy] = positions[i];
          const x = cx + dx, y = cy + dy;
          if (s.type === 'x' || (s.type === 'mixed' && i >= 2)) {
            const a = document.createElementNS('http://www.w3.org/2000/svg','path');
            a.setAttribute('d', `M ${x-13} ${y-24} Q ${x} ${y} ${x+13} ${y+24} M ${x+13} ${y-24} Q ${x} ${y} ${x-13} ${y+24}`);
            svgGroup.appendChild(a);
          } else {
            const l = document.createElementNS('http://www.w3.org/2000/svg','line');
            l.setAttribute('x1', x); l.setAttribute('y1', y-23);
            l.setAttribute('x2', x); l.setAttribute('y2', y+23);
            svgGroup.appendChild(l);
          }
          const c = document.createElementNS('http://www.w3.org/2000/svg','circle');
          c.setAttribute('cx', x); c.setAttribute('cy', y); c.setAttribute('r', '4');
          centromeres.appendChild(c);
        }
      }

      function select(stage) {
        const s = stages[stage];
        buttons.forEach(b => b.dataset.active = String(b.dataset.stage === stage));
        document.getElementById('stage-title').textContent = `${stage}階段`;
        document.getElementById('ploidy-badge').textContent = `${s.ploidy} = ${s.count}`;
        document.getElementById('appear-badge').textContent = s.appear;
        document.getElementById('count-value').textContent = s.count;
        document.getElementById('ploidy-value').textContent = s.ploidy;
        document.getElementById('possible-value').textContent = s.possible;
        document.getElementById('visual-note').textContent = s.note;
        document.getElementById('explain').innerHTML = s.explain;
        draw(stage);
      }

      buttons.forEach(b => b.addEventListener('click', () => select(b.dataset.stage)));
      select('甲');
    })();
  </script>
</div>"}}

